
.meter-section {
  padding: 6px 10px;
  border-bottom: 1px solid var(--c-border);
}

.meter-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 3px;
}

.label {
  font-weight: bold;
  font-size: 11px;
  color: var(--c-suspicion);
}

.hint {
  font-size: 10px;
  color: var(--c-text-muted);
}

.track {
  height: 8px;
  background: var(--c-bar-bg);
  border: 1px solid var(--c-border);
  overflow: hidden;
}

.fill {
  height: 100%;
  background: var(--c-suspicion);
  transition: width 0.3s ease;
}

.meter-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 3px;
}

.value {
  font-size: 10px;
  color: var(--c-text-muted);
}

.controls {
  display: flex;
  gap: 2px;
}

.controls button {
  padding: 0 5px;
  font-size: 10px;
  font-family: inherit;
  border: 1px solid var(--c-border);
  background: var(--c-card);
  cursor: pointer;
}

.controls button:active:not(:disabled) {
  background: var(--c-bar-bg);
}

.controls button:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}
