
.affection-section {
  padding: 8px 10px;
  border-bottom: 1px solid var(--c-border);
}

.affection-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 4px;
}

.label {
  font-weight: bold;
  font-size: 12px;
}

.stage-badge {
  font-size: 10px;
  padding: 1px 6px;
  border: 1px solid var(--c-border);
  color: #fff;
  font-weight: bold;
  letter-spacing: 0.5px;
}

.stage-初识 { background: var(--c-accent); }
.stage-动摇 { background: #c4893c; }
.stage-越界 { background: var(--c-guilt); }
.stage-沦陷 { background: var(--c-affection); }

.track {
  position: relative;
  height: 12px;
  background: var(--c-bar-bg);
  border: 1px solid var(--c-border);
  overflow: hidden;
}

.fill {
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  background: var(--c-affection);
  transition: width 0.3s ease;
}

.ticks {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.tick {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 1px;
  background: rgba(0, 0, 0, 0.15);
}

.affection-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 4px;
}

.value {
  font-size: 11px;
  color: var(--c-text-muted);
}

.controls {
  display: flex;
  gap: 3px;
}

.controls button {
  padding: 1px 6px;
  font-size: 10px;
  font-family: inherit;
  border: 1px solid var(--c-border);
  background: var(--c-card);
  cursor: pointer;
}

.controls button:active:not(:disabled) {
  background: var(--c-bar-bg);
}

.controls button:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}
